/* AIVIC_FUNCTION_BUNDLE_START owner=formatSubmissionStatusTimeline exports=formatSubmissionStatusTimeline */
const __aivicBundle_7_formatSubmissionStatusTimeline = (() => {
  interface SubmissionStatusTimelineInput {
    startDateTime: Date;
    endDateTime: Date;
    teamId?: string;
    requestingUserId: string;
  }
  
  class InvalidDateRangeError extends Error {
    constructor(message: string) {
      super(message);
      this.name = 'InvalidDateRangeError';
    }
  }
  
   function formatSubmissionStatusTimeline(
    input: SubmissionStatusTimelineInput
  ): SubmissionStatusTimelineOutput {
    const { startDateTime, endDateTime, teamId, requestingUserId } = input;
  
    if (startDateTime > endDateTime) {
      throw new InvalidDateRangeError('開始日時が終了日時より後です');
    }
  
    const { retrieveReportsByDateRange } = require('./report-persistence');
    const { filterDisplayContentByRole } = require('./access-control-and-permissions');
  
    const reportQuery = {
      startDate: startDateTime.toISOString(),
      endDate: endDateTime.toISOString(),
      ...(teamId && { teamId }),
    };
  
    const retrievedDataset = retrieveReportsByDateRange(reportQuery);
    const reports = retrievedDataset.reports || [];
  
    const filterInput = {
      userContext: {
        userId: requestingUserId,
        role: 'viewer',
      },
      contentType: 'daily_report' as const,
      ...(teamId && { targetTeamId: teamId }),
      dataSet: {
        reports,
        timelineRange: {
          start: startDateTime.toISOString(),
          end: endDateTime.toISOString(),
        },
      },
    };
  
    const filteredContent = filterDisplayContentByRole(filterInput);
    const visibleReports = (filteredContent.filteredData?.reports as any[]) || [];
  
    const timelineDataPoints: Array<{
      timestamp: Date;
      submittedCount: number;
      unsubmittedCount: number;
      submissionRate: number;
    }> = [];
  
    const hourlyBuckets = new Map<
      string,
      { submitted: Set<string>; total: Set<string> }
    >();
  
    const currentTime = new Date(startDateTime);
    while (currentTime <= endDateTime) {
      const hourKey = currentTime.toISOString().slice(0, 13);
      if (!hourlyBuckets.has(hourKey)) {
        hourlyBuckets.set(hourKey, { submitted: new Set(), total: new Set() });
      }
      currentTime.setHours(currentTime.getHours() + 1);
    }
  
    visibleReports.forEach((report: any) => {
      const reportTime = new Date(report.submissionTimestamp || report.createdAt);
      if (reportTime >= startDateTime && reportTime <= endDateTime) {
        const hourKey = reportTime.toISOString().slice(0, 13);
        const bucket = hourlyBuckets.get(hourKey);
        if (bucket) {
          const reporterId = report.submittedByUserId || report.reporterId;
          bucket.submitted.add(reporterId);
          bucket.total.add(reporterId);
        }
      }
    });
  
    const allReporterIds = new Set<string>();
    hourlyBuckets.forEach((bucket) => {
      bucket.total.forEach((id) => allReporterIds.add(id));
    });
    const totalMembersCount = Math.max(allReporterIds.size, 1);
  
    const sortedHours = Array.from(hourlyBuckets.keys()).sort();
    sortedHours.forEach((hourKey) => {
      const bucket = hourlyBuckets.get(hourKey)!;
      const submittedCount = bucket.submitted.size;
      const unsubmittedCount = totalMembersCount - submittedCount;
      const submissionRate =
        totalMembersCount > 0
          ? Math.round((submittedCount / totalMembersCount) * 100)
          : 0;
  
      timelineDataPoints.push({
        timestamp: new Date(hourKey + ':00:00Z'),
        submittedCount,
        unsubmittedCount,
        submissionRate,
      });
    });
  
    return {
      timelineDataPoints,
      aggregationPeriod: {
        startDateTime,
        endDateTime,
      },
      totalMembersCount,
    };
  }
  return { formatSubmissionStatusTimeline };
})();
export const formatSubmissionStatusTimeline = __aivicBundle_7_formatSubmissionStatusTimeline.formatSubmissionStatusTimeline;
